import runpy,re
from pathlib import Path
p=Path(__file__).parent
d=runpy.run_path(str(p/'build.py')); scenes=d['scenes']; visual=d['visual']; s=(p/'storyboard.html').read_text()
def setscene(i,**fields):
 a=list(scenes[i]); keys=['n','title','loc','k','caption','line','story','play','origin','op','scope','state']
 for k,v in fields.items():a[keys.index(k)]=v
 scenes[i]=tuple(a)
setscene(0,loc='LOWER FLOOR · PARLOR · 2 MIN',play='Give a printed map and pencil: <b>four seals → four offerings → inheritance.</b> Deal four public roles: Witness, Listener, Speaker, Keeper; abilities are transferable as people leave. Hand out one supplied offering token each. Explain that a sacrifice ends that player’s game, and confirm a willing blindfold participant privately before dealing. Pause after every instruction.',op='Captain plays the medium; Tamari the attendant. Start restrained parlor audio. The inheritance chest is in plain sight. Keep the blindfold participant on one level throughout; the physical layout is lower-floor finished living space plus basement, with actual doors and level changes still to verify.')
setscene(1,loc='PARLOR · FALSE TEST · 2 MIN',play='<b>Rigged draft:</b> guess a card rank, but the concealed card is a blank mourning card, so no legal answer wins. Spend the <b>Veiled</b> curse: a willing player puts on a blindfold and remains blind through their ending. The ghost calls this player “the last witness” and refuses to accept them before the final offering. This proposed rule preserves the captain’s blind survivor while the others may be chosen in any order.',op='Tamari gives a manual knock cue and applies the curse. The blind player gets a large tactile star to identify their role. Optional Menace overlay goes to a different player: suggest one wrong answer or delay for 20 seconds, then cooperate. Never move objects or people to obstruct the blind player.',origin='Captain: forced curse and, in the correction, at least one player remaining blind until the end. New draft: permanent Veiled curse, willing last witness protected from early sacrifice, blank-card rig.',state='4 present · 0 seals · 1 permanently blind')
setscene(2,loc='STUDY STATION · SIGHT → SACRIFICE 1 · 4 MIN',play='Align the large grille over a well-lit letter: four windows reveal <b>B E L L</b>. Select the BELL drawer; gain seal 1 and a keepsake. A sighted teammate reads while the blind player aligns a tactile corner or holds the map. Then the mother demands a bearer to “carry this memory home.” Choose one of the three sighted guests: Captain and Tamari enter, escort that player out, and return to resume the game. <b>4 → 3.</b>',op='Captain and Tamari jointly take the first guest through the nearby exit threshold. Tamari completes the short handoff to the lit party/refreshment area; Captain returns immediately to the remaining group. Pause the puzzle clock and use a short audio interlude during this handoff. The sacrificed guest leaves the game; give them a child-name card and a private “Mother has claimed you” line.',state='3 remain · 1 / 4 seals · blind witness stays')
setscene(3,loc='HEARTH STATION · HEARING → SACRIFICE 2 · 4 MIN',play='Play an intelligible <b>3–1–4</b> whisper plus grouped knocks. The blind player can hear, repeat and direct the code; a sighted teammate operates the box. Gain seal 2 and its keepsake. Then choose one of the two remaining sighted players to “bring light to the bearer.” Both collectors enter and remove them. <b>3 → 2: one blind, one sighted.</b>',op='Quiet background audio for the clue. Manual replay and spoken hints keep it legible. Captain and Tamari repeat the short escort handoff. Do not give the blind witness a hearing curse; the last two must retain at least one useful hearing channel. A stalled group pays an expendable offering or a compatible temporary curse and receives the seal.',state='2 remain · 2 / 4 seals · one blind / one sighted')
setscene(4,loc='HEARTH / TABLE · TOUCH → SACRIFICE 3 · 4 MIN',play='The blind player feels three large shapes and retrieves the ridged star matching their tactile sample; the sighted partner reads the instruction and positions the box. Gain seal 3. Move the pair to the final table <b>before</b> removal; the blind witness is seated with the remaining props in reach. Captain and Tamari remove the final sighted teammate as “the one who must open the way.” <b>2 → 1.</b>',op='Tamari performs the optional brief touch from a side opening; Captain guides the pair to the table. During the third escort Captain returns immediately to the blind witness while Tamari finishes the guest’s exit handoff. Audio sustains the scene; never leave a blind guest navigating alone. The guest may remove the blindfold at any time; this stops that restriction, not their real ability to exit.',state='1 remains · 3 / 4 seals · blind witness seated')
setscene(5,title='Alone, she knows your voice',loc='SEANCE TABLE · SPEECH / HYPNOSIS · 3 MIN',caption='Three voices have gone. The fourth can no longer see who is listening.',line='“They are waiting for you. Speak, and I will open the house.”',story='The mother addresses the blind survivor directly. A short theatrical breathing/countdown ritual supplies the hypnosis layer without demanding actual susceptibility. The player becomes the only person who can complete the spoken seal.',play='Use <b>four tactile tiles with 1–4 raised dots</b>. The mother speaks one word with each numbered knock: 1 OPEN, 2 THE, 3 HOUSE, 4 AGAIN. The blind player orders the tiles and repeats the phrase. Give seal 4 in a distinct raised frame. Unlimited replay, one-word hints and operator positioning preserve a real hearing/touch/speech task for one person.',op='Captain positions props within reach and operates the voice cue; Tamari resets the exit handoff and returns. No sight, second player or reading is required. Clear any optional speech or hand curse before this scene; <b>the blindness stays</b>. The possible healer cannot lift the protected Veiled curse.',origin='Captain: blindness persists to the end; hypnosis, speech curse and healer were earlier possibilities. New draft: solo tactile/audio phrase puzzle and explicit protected ability channels.',state='1 blind survivor · 4 / 4 seals')
setscene(6,loc='SEANCE TABLE · OUIJA · 3 MIN',caption='The survivor feels the planchette move. Every letter is spoken from the dark.',play='The survivor places the four keepsakes in a large felt ring by touch. Captain guides their fingertips onto the planchette. The XY magnet spells <b>OFFER → ONE</b>; the spirit voice reads the letters and then the complete message aloud. The camera checks that a hand is present. The final “one” is the player. A static board with voice remains the fallback.',op='Manual GO authorizes movement; camera readiness alone never launches it. <b>At least one hand, not four, is the working gate for the solo finale.</b> No hands means stop. Use light fingertip contact; operator monitors. To let sighted guests witness the signature effect too, optionally add one short board motion during arrival—but only if already reliable.',origin='Captain: XY/camera board plus the shrinking team and blind ending. New draft: audible letter echo, single-hand finale, optional early demonstration.',state='1 blind survivor · four offerings laid')
setscene(7,title='The final false choice',loc='SEANCE TABLE · FINAL SACRIFICE · 2 MIN',caption='There is no companion left to send. The voice offers two doors.',line='“Will you go to them, or shall they come to you?”',story='Either answer claims the fourth life. The mother’s real intent becomes unmistakable. This is the last sacrifice after three earlier removals; the remaining player never has to solve a puzzle with no usable sense.',play='Both answers cue the final claim. Captain and Tamari physically take charge of the survivor at the table: one offers a guiding arm, the other opens the threshold. Deliver the ending <b>while the survivor is still seated and blind</b>, then guide them out. If the footprint permits a flat short escort before the ending, rehearse it with the same two guides; no stairs under blindfold.',op='The blindness persists throughout the in-game reveal. No dragging or restraint. The final spoken line marks the end of the game; only then invite the guest to remove the blindfold before the real exit. This staging meets the blind ending without relying on a visual payoff.',origin='Captain correction: removals throughout; at least one guest ends blind. New draft: seated claim/reveal followed by guided exit, two false answers.',state='1 → 0 in game · final guest stays blind')
setscene(8,title='Mother has four children again',loc='TABLE → LIT PARTY EXIT · 1 MIN',caption='Four children answer “Mother.” The last voice is addressed by a name that is not theirs.',line='“You came for an inheritance. You are the inheritance. Four lives for four lives. My children are home.”',story='The blind guest hears all four child voices and feels a child-name plaque placed in their hand. The mother names the bargain explicitly: the players’ sacrificed lives restored her children. A silhouette and optional fog reward sighted observers, but the final guest receives the whole reveal through sound and touch.',play='End the story aloud: “The house releases you. The game is over.” Invite blindfold removal and guide to the lit party area. Earlier sacrifices are already out enjoying the party; they need not reconvene or see this ending. Their exit cards provide a short epilogue. The possession-style variant—players becoming the children—remains a clearly held alternative.',op='Tamari supplies the tactile plaque; Captain triggers the four voices. No third performer required. Removed guests receive thanks, a comfortable route to refreshments and a request not to spoil the remaining run. The finale must work with the silhouette and fog switched off.',origin='Captain: four sacrifices restore children, terrible prize, no need for everyone to reach the end. Firstmate: the players as restored children. New draft: audio/tactile ending and pleasant early-exit epilogues.',state='All four sacrificed · guests return to party separately')
for n,title,loc,k,caption,line,story,play,origin,op,scope,state in scenes:
 block=f'<article class="scene" id="scene-{n}"><div class="scene-top">{visual(k)}<div class="scene-intro"><span class="number">{n}</span><div class="eyebrow">{loc}</div><h3>{title}</h3><p>{caption}</p><div class="badges"><span class="badge badge-outline">{scope}</span><span class="badge badge-ghost">{state}</span></div></div></div><div class="scene-body"><blockquote>{line}</blockquote><p>{story}</p><div class="mechanics"><div class="labelhead">What players do</div><p>{play}</p></div><details class="operator"><summary>Operator cue & idea provenance</summary><p>{op}</p><p class="caption">{origin}</p></details></div></article>'
 s=re.sub(f'<article class="scene" id="scene-{n}">.*?</article>',lambda _:block,s,flags=re.S)
start=s.index('<pre class="mermaid">');end=s.index('</pre>',start)+6
s=s[:start]+'''<pre class="mermaid">flowchart TD
 A["01 Four arrive: roles + map"] --> B["02 Rigged test: one permanently blind"]
 B --> C["03 Sight seal: sacrifice 1; four to three"]
 C --> D["04 Hearing seal: sacrifice 2; three to two"]
 D --> E["05 Touch seal: seat blind witness; sacrifice 3"]
 E --> F["06 One blind survivor: tactile + spoken seal"]
 F --> G["07 Solo Ouija: feel motion + hear letters"]
 G --> H["08 Final claim: either choice sacrifices witness"]
 H --> I["09 Blind audio-tactile ending; game over; exit"]
 C -.-> X["Removed guest leaves game for lit party area"]
 D -.-> X
 E -.-> X
</pre>'''+s[end:]
